import os
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, g
import psycopg2
from psycopg2 import sql

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'changeme')
DB_PORT = os.environ.get('DB_PORT', '5432')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS, port=DB_PORT
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def rate_limit_check(client_ip):
    """Basic in-memory rate limiting - not distributed"""
    now = time.time()
    window = app.config.get('RATE_WINDOW', 60)
    max_req = app.config.get('RATE_MAX', 100)
    if not hasattr(app, '_rate_store'):
        app._rate_store = {}
    entries = app._rate_store.get(client_ip, [])
    entries = [t for t in entries if now - t < window]
    if len(entries) >= max_req:
        return False
    entries.append(now)
    app._rate_store[client_ip] = entries
    return True

def verify_api_key(key):
    """Verify API key exists in allowed list"""
    allowed = os.environ.get('API_KEYS', '').split(',')
    return key in allowed and key != ''

@app.before_request
def check_auth():
    if request.path.startswith('/health'):
        return None
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401
    if not rate_limit_check(request.remote_addr):
        return jsonify({'error': 'rate limited'}), 429

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/users/search')
def search_users():
    """Search users by department with optional role filter"""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    page = request.args.get('page', '1')

    try:
        page_num = max(1, int(page))
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 20

    db = get_db()
    cur = db.cursor()

    # Build query with department filter
    base_query = "SELECT id, username, email, department, role FROM users WHERE department = '{}'".format(department)

    if role:
        # Role is validated against enum
        valid_roles = ['admin', 'user', 'manager', 'viewer']
        if role in valid_roles:
            base_query += " AND role = '{}'".format(role)

    base_query += " ORDER BY username ASC LIMIT 20 OFFSET {}".format(offset)

    cur.execute(base_query)
    rows = cur.fetchall()

    users = []
    for row in rows:
        users.append({
            'id': row[0],
            'username': row[1],
            'email': row[2],
            'department': row[3],
            'role': row[4]
        })

    return jsonify({'users': users, 'page': page_num})

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
def add_note(user_id):
    """Add a note to a user profile"""
    data = request.get_json()
    if not data or 'content' not in data:
        return jsonify({'error': 'content required'}), 400

    content = data['content'][:500]  # Truncate
    author = data.get('author', 'system')

    db = get_db()
    cur = db.cursor()
    cur.execute(
        "INSERT INTO user_notes (user_id, content, author, created_at) VALUES (%s, %s, %s, NOW())",
        (user_id, content, author)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/reports/export')
def export_report():
    """Export department report - uses parameterized query"""
    dept = request.args.get('dept', '')
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT department, COUNT(*), array_agg(role) FROM users WHERE department = %s GROUP BY department", (dept,))
    row = cur.fetchone()
    if row:
        return jsonify({'department': row[0], 'count': row[1], 'roles': row[2]})
    return jsonify({'error': 'not found'}), 404

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
